/**
 * Repairs the sales table using the report already generated by
 * diag-verify-sales-onchain.js (wrong-sales-rows-report.json) -- 1,271 rows
 * confirmed wrong by directly checking each transaction's real on-chain
 * logs, not by inference. This script deletes EXACTLY those row ids and
 * nothing else.
 *
 * Defaults to a dry run (just previews what would happen). Set WRITE=true
 * to actually delete anything, matching the same safety pattern used for
 * every other data-mutating script this session.
 *
 * USAGE
 *   node repair-wrong-sales-rows.js                  (dry run, default)
 *   WRITE=true node repair-wrong-sales-rows.js        (actually deletes)
 */

require('dotenv').config();
const fs = require('fs');
const path = require('path');
const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false } });

const WRITE = process.env.WRITE === 'true';

async function main() {
  const reportPath = path.join(__dirname, 'wrong-sales-rows-report.json');
  if (!fs.existsSync(reportPath)) {
    console.log(`Report not found at ${reportPath} -- run diag-verify-sales-onchain.js first.`);
    process.exit(1);
  }
  const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));
  const ids = report.wrongRows.map(r => r.id);

  console.log(`\nLoaded report from ${new Date(report.generatedAt).toLocaleString()}`);
  console.log(`  Confirmed-wrong rows to delete: ${ids.length}`);
  console.log(`  (Confirmed-correct rows, untouched: ${report.confirmedCorrect})`);

  if (!ids.length) {
    console.log('\nNothing to delete.');
    return;
  }

  // Sanity check: confirm these row ids still exist and still look like
  // what the report expects, before touching anything -- the sales table
  // could have changed since the report was generated.
  const checkRes = await pool.query(`SELECT id, token_id, tx_hash FROM sales WHERE id = ANY($1::bigint[])`, [ids]);
  console.log(`  Rows currently found in the database matching these ids: ${checkRes.rows.length} (expected ${ids.length})`);
  if (checkRes.rows.length !== ids.length) {
    console.log('  NOTE: mismatch -- some rows may have already been deleted/changed since the report ran.');
  }

  if (!WRITE) {
    console.log('\nDRY RUN -- no changes made. Showing the first 10 rows that would be deleted:\n');
    for (const r of checkRes.rows.slice(0, 10)) {
      console.log(`  id=${r.id}  token_id=${r.token_id}  tx_hash=${r.tx_hash}`);
    }
    console.log(`\n...and ${Math.max(0, checkRes.rows.length - 10)} more.`);
    console.log('\nRe-run with WRITE=true to actually delete these rows.');
    return;
  }

  console.log('\nWRITE=true -- deleting confirmed-wrong rows now...');
  const delRes = await pool.query(`DELETE FROM sales WHERE id = ANY($1::bigint[])`, [ids]);
  console.log(`Deleted ${delRes.rowCount} row(s) (expected ${ids.length}).`);
  if (delRes.rowCount !== ids.length) {
    console.log('NOTE: actual deleted count did not match expected -- worth double-checking manually.');
  } else {
    console.log('Counts match exactly. Repair complete.');
  }
}

main().then(() => pool.end()).catch(e => { console.error('Fatal error:', e.message); pool.end(); process.exit(1); });
